          aria-hidden
          className={cn(
            "pointer-events-none absolute -top-10 right-0 select-none font-display text-[120px] font-black leading-none tracking-[-0.05em] [-webkit-text-stroke:1.5px_currentColor] [color:transparent] opacity-[0.07] sm:text-[160px]",
            ink ? "text-background" : "text-foreground",
          )}
        >
          {index}
        </span>
      )}
      {eyebrow && (
        <MonoLabel className={cn("mb-5", ink ? "text-background/55" : "text-muted-foreground", align === "center" && "justify-center")}>
          {eyebrow}
        </MonoLabel>
      )}
      <h2 className={cn("font-display text-[34px] font-black leading-[0.98] tracking-[-0.035em] sm:text-[44px] lg:text-[52px]", ink ? "text-background" : "text-foreground")}>
        {title}
      </h2>
      {subtitle && (
        <p className={cn("mt-4 text-[15px] font-medium leading-[1.7] sm:text-base", ink ? "text-background/65" : "text-muted-foreground", align === "left" && "max-w-xl")}>
          {subtitle}
        </p>
      )}
    </header>
  )
}

// ── Ordinal — numbered tick for lists/cards ("01 /") ─────────────────────────
export function Ordinal({ n, total, className }: { n: number; total?: number; className?: string }) {
  return (
    <span className={cn("font-mono text-[11px] font-bold uppercase tracking-[0.2em] opacity-60", className)}>
      {String(n).padStart(2, "0")}
      {total ? <span className="opacity-50"> / {String(total).padStart(2, "0")}</span> : <span aria-hidden> /</span>}
    </span>
  )
}

// Vendored from Bklit UI (MIT) — https://github.com/bklit/bklit-ui · packages/ui/src/components/shimmering-text.tsx — fetched 2026-09-01
// Adapted: relocated to primitives per vendoring contract ("@/components/shimmering-text" → "@/components/primitives/shimmering-text"); stripped "use client" directive (library build)

import { motion, useReducedMotion, type Variants } from "motion/react";
import { type ComponentProps, useCallback } from "react";
import { cn } from "@/lib/utils";

export type ShimmeringTextProps = Omit<
  ComponentProps<typeof motion.span>,
  "children"
> & {
  /** The text to render with the shimmering effect. */
  text: string;
  /**
   * Duration in seconds for one shimmer cycle.
   * @defaultValue 1
   */
  duration?: number;
  /**
   * Pause the shimmer (e.g. when the hero leaves the viewport).
   * @defaultValue false
   */
  paused?: boolean;
  /**
   * Legacy alias for `paused`.
   * @defaultValue false
   */
  isStopped?: boolean;
};

export function ShimmeringText({
  text,
  duration = 1,
  isStopped = false,
  paused = false,
  className,
  ...props
}: ShimmeringTextProps) {
  const reducedMotion = useReducedMotion();
  const stopped = isStopped || paused || reducedMotion === true;

  const createCharVariants = useCallback(
    (charIndex: number): Variants => ({
      running: {
        color: ["var(--color)", "var(--shimmering-color)", "var(--color)"],
        transition: {
          duration,
          repeat: Number.POSITIVE_INFINITY,
          repeatType: "loop",
          repeatDelay: text.length * 0.05,
          delay: (charIndex * duration) / text.length,
          ease: "easeInOut",
        },
      },
      stopped: {
        color: "var(--color)",
        transition: {
          duration: duration * 0.5,
          ease: "easeOut",
        },
      },
    }),
    [duration, text.length]
  );

  return (
    <motion.span
      className={cn(
        "inline-flex select-none items-center leading-none",
        "[--color:var(--muted-foreground)] [--shimmering-color:var(--foreground)]",
        className
      )}
      {...props}
    >
      {text.split("").map((char, index) => (
        <motion.span
          animate={stopped ? "stopped" : "running"}
          aria-hidden
          className="inline-block whitespace-pre leading-none"
          initial="stopped"
          // biome-ignore lint/suspicious/noArrayIndexKey: static label text, order never changes
          key={index}
          variants={createCharVariants(index)}
        >
          {char}
        </motion.span>
      ))}
      <span className="sr-only">{text}</span>
    </motion.span>
  );
}
